    if (was.el.matches('img')) setAttr(was.el, 'src', was.src);
    textAfterPic = false;
    const i = pages.indexOf(pageOf(was.el));
    if (i !== index) go(i); // \uB2E4\uB978 \uCABD\uC758 \uADF8\uB9BC\uC774\uBA74 \uBB34\uC5C7\uC774 \uB418\uB3CC\uC544\uAC14\uB294\uC9C0 \uBCF4\uC774\uAC8C \uADF8 \uCABD\uC73C\uB85C \uAC04\uB2E4
